import {progressFloors,progressRooms,progressFloor} from './progress-scope.mjs';
import {matchPma,pmaWarnings,pmaDifferences} from './pma-model.mjs';
export const installation=['Sin registrar','No iniciado','En proceso','Instalado'];
export const quality=['Sin revisar','Con observaciones','Conforme'];
export const fields={PAV:'Pavimento',CIE:'Cielo',M1:'Muro norte',M2:'Muro oriente',M3:'Muro sur',M4:'Muro poniente'};
export const keyFor=(code,level='N-1')=>level+'|'+code.trim();
export function tasksFor(model,room,level='N-1'){if(progressFloor(room.level)!==level)return [];const match=matchPma(model,room,level);if(match.state!=='matched')return [];return Object.entries(fields).map(([field,name])=>{const code=String(match.row[field]??'').trim();return {field,name,code,description:model.materials.get(code)||'Descripción pendiente',applicable:!['N/A','-'].includes(code),documented:!!code&&model.materials.has(code),asepsis:match.row.asepsis};});}
export function validateRecord(r){if(!progressFloors[r?.level]||typeof r.code!=='string'||r.key!==keyFor(r.code,r.level)||!Number.isInteger(r.version)||r.version<1||!r.responsible?.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date).toISOString().slice(0,10)!==r.date||!/^[a-f0-9]{64}$/.test(r.sourceSha)||typeof r.notes!=='string'||r.notes.length>10000||!r.fields||typeof r.at!=='string')throw Error('Registro de avance incompleto.');for(const [f,v] of Object.entries(r.fields)){if(!fields[f]||!installation.includes(v.installation)||!quality.includes(v.quality)||typeof v.code!=='string'||typeof v.missing!=='string'||typeof v.notes!=='string'||v.notes.length>5000||v.missing.length>5000||v.quality==='Conforme'&&(v.installation!=='Instalado'||v.missing.trim())||v.quality==='Con observaciones'&&!v.notes.trim())throw Error('Revisa estado, condición y observaciones de '+(fields[f]||f));}return r;}
export function reportProgress(model,rooms,records,level='N-1'){const index=new Map(records.filter(r=>r.level===level&&r.key===keyFor(r.code,level)).map(r=>[r.key,r])),rows=progressRooms(rooms,level).map(room=>{const record=index.get(keyFor(room.code,level)),tasks=tasksFor(model,room,level).filter(t=>t.applicable).map(t=>{const saved=record?.fields[t.field],current=record?.sourceSha===model.source.sha256&&saved?.code===t.code;return {...t,installation:current?saved.installation:'Sin registrar',quality:current?saved.quality:'Sin revisar',missing:saved?.missing||'',notes:saved?.notes||'',stale:!!saved&&!current};});const complete=tasks.length>0&&tasks.every(t=>t.documented&&t.installation==='Instalado'&&t.quality==='Conforme');const pma=matchPma(model,room,level);return {room,record,tasks,complete,pmaState:pma.state,warnings:pma.row?[...pmaWarnings(model,pma.row),...(pmaDifferences(room,pma.row).length?['PMA y plano tienen códigos diferentes: cotejar antes de ejecutar.']:[])]:['Sin correspondencia PMA']};});const tasks=rows.flatMap(r=>r.tasks),eligible=tasks.filter(t=>t.documented);return {level,rows,withoutPma:rows.filter(r=>r.pmaState!=='matched').length,tasks:eligible,unknown:tasks.filter(t=>!t.documented).length,total:eligible.length,installed:eligible.filter(t=>t.installation==='Instalado').length,accepted:eligible.filter(t=>t.installation==='Instalado'&&t.quality==='Conforme').length,observed:eligible.filter(t=>t.quality==='Con observaciones').length,complete:rows.filter(r=>r.complete).length};}
